"""Central judge. Uploaded traces are data only; no participant code is executed."""

import base64
import csv
import hashlib
import hmac
import io
import json
import os
import secrets
import threading
import time
from dataclasses import dataclass
from datetime import UTC, datetime
from importlib.resources import files
from pathlib import Path
from typing import Annotated
from urllib.parse import unquote

from fastapi import Depends, FastAPI, HTTPException, Request, Response
from fastapi.responses import FileResponse, JSONResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel, ConfigDict, Field, field_validator
from starlette.concurrency import run_in_threadpool

from .core import PUZZLE_VERSION, Challenge, iso_date, puzzle_metadata
from .storage import Store
from .validation import DEFAULT_MAX_ACTIONS, DEFAULT_MAX_BYTES, validate_trace


@dataclass(frozen=True)
class Settings:
    database: Path
    admin_password: str
    secret: str
    secure_cookie: bool = False
    max_bytes: int = DEFAULT_MAX_BYTES
    max_actions: int = DEFAULT_MAX_ACTIONS

    def __post_init__(self):
        if len(self.admin_password) < 12 or len(self.secret) < 32:
            raise ValueError(
                "Set an admin password of at least 12 chars and a secret of at least 32"
            )
        if self.max_bytes < 1 or self.max_actions < 1:
            raise ValueError("Upload/action limits must be positive")

    @classmethod
    def from_env(cls, database: Path):
        return cls(
            database,
            os.getenv("DAYDOKUTHON_ADMIN_PASSWORD", ""),
            os.getenv("DAYDOKUTHON_SECRET", ""),
            os.getenv("DAYDOKUTHON_SECURE_COOKIE", "false").lower() == "true",
            int(os.getenv("DAYDOKUTHON_MAX_BYTES", str(DEFAULT_MAX_BYTES))),
            int(os.getenv("DAYDOKUTHON_MAX_ACTIONS", str(DEFAULT_MAX_ACTIONS))),
        )


def utc_now() -> datetime:
    return datetime.now(UTC)


def timestamp(value: datetime) -> str:
    return value.astimezone(UTC).isoformat()


def as_challenge(row: dict) -> Challenge:
    return Challenge(row["id"], iso_date(row["date"]), row["title"], row["puzzle_version"])


def eligibility(row: dict, received: datetime) -> tuple[bool, str]:
    if row["closed"]:
        return False, "challenge_closed"
    if row["opens_at"] and received < datetime.fromisoformat(row["opens_at"]):
        return False, "before_opening"
    if row["closes_at"] and received >= datetime.fromisoformat(row["closes_at"]):
        return False, "after_deadline"
    return True, "within_window"


class Login(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    password: str = Field(max_length=1024)


class NewChallenge(BaseModel):
    model_config = ConfigDict(extra="forbid")
    title: str = Field(min_length=1, max_length=120, strict=True)
    date: str
    opens_at: datetime | None = None
    closes_at: datetime | None = None

    @field_validator("date")
    @classmethod
    def calendar_date(cls, value):
        iso_date(value)
        return value

    @field_validator("opens_at", "closes_at")
    @classmethod
    def timezone_required(cls, value):
        if value is not None and value.tzinfo is None:
            raise ValueError("Include an explicit timezone in opening/closing timestamps")
        return value


async def bounded_body(request: Request, limit: int) -> bytes:
    chunks, size = [], 0
    async for chunk in request.stream():
        size += len(chunk)
        if size > limit:
            raise HTTPException(413, "Upload exceeds the configured byte limit")
        chunks.append(chunk)
    return b"".join(chunks)


def _assets(application: FastAPI):
    root = Path(str(files("daydokuthon").joinpath("assets")))
    application.mount("/assets", StaticFiles(directory=root), name="assets")

    @application.get("/", include_in_schema=False)
    def index():
        return FileResponse(root / "index.html")

    @application.get("/organizer", include_in_schema=False)
    def organizer():
        return FileResponse(root / "index.html")


def _headers(application: FastAPI):
    @application.middleware("http")
    async def security_headers(request: Request, call_next):
        response = await call_next(request)
        response.headers["Cache-Control"] = "no-store"
        response.headers["Referrer-Policy"] = "no-referrer"
        response.headers["X-Content-Type-Options"] = "nosniff"
        response.headers["Content-Security-Policy"] = (
            "default-src 'self'; script-src 'self'; style-src 'self'; "
            "img-src 'self' data:; frame-ancestors 'none'; base-uri 'none'; form-action 'self'"
        )
        return response


def create_app(settings: Settings) -> FastAPI:
    app = FastAPI(title="Daydokuthon", version="0.1.0")
    store = Store(settings.database)
    app.state.store = store
    _headers(app)
    salt = secrets.token_bytes(16)
    password_hash = hashlib.pbkdf2_hmac("sha256", settings.admin_password.encode(), salt, 200_000)
    signing_key = settings.secret.encode()
    failures: dict[str, list[float]] = {}
    login_lock = threading.Lock()

    def signed_session(csrf: str) -> str:
        payload = base64.urlsafe_b64encode(
            json.dumps({"exp": int(time.time()) + 8 * 3600, "csrf": csrf}).encode()
        ).decode()
        return payload + "." + hmac.new(signing_key, payload.encode(), "sha256").hexdigest()

    def session(request: Request) -> dict | None:
        try:
            payload, signature = request.cookies.get("daydokuthon_session", "").split(".")
            expected = hmac.new(signing_key, payload.encode(), "sha256").hexdigest()
            if not hmac.compare_digest(signature, expected):
                return None
            data = json.loads(base64.urlsafe_b64decode(payload))
            return data if data["exp"] > time.time() else None
        except (ValueError, KeyError, TypeError):
            return None

    def origin_check(request: Request):
        origin = request.headers.get("origin")
        if origin and origin != str(request.base_url).rstrip("/"):
            raise HTTPException(403, "Cross-origin organizer request rejected")

    def admin(request: Request) -> dict:
        data = session(request)
        if not data:
            raise HTTPException(401, "Organizer login required")
        if request.method not in ("GET", "HEAD"):
            origin_check(request)
            if not hmac.compare_digest(request.headers.get("x-csrf-token", ""), data["csrf"]):
                raise HTTPException(403, "Missing or invalid CSRF token")
        return data

    Admin = Annotated[dict, Depends(admin)]

    @app.get("/health")
    def health():
        return {"status": "ok"}

    @app.get("/api/config")
    def config():
        return {
            "mode": "central",
            "max_bytes": settings.max_bytes,
            "max_actions": settings.max_actions,
        }

    @app.post("/api/admin/login")
    def login(body: Login, request: Request, response: Response):
        origin_check(request)
        address = request.client.host if request.client else "unknown"
        with login_lock:
            recent = [t for t in failures.get(address, []) if t > time.monotonic() - 60]
            if len(recent) >= 5:
                raise HTTPException(429, "Too many login attempts; wait one minute")
            failures[address] = recent + [time.monotonic()]
        actual = hashlib.pbkdf2_hmac("sha256", body.password.encode(), salt, 200_000)
        if not hmac.compare_digest(actual, password_hash):
            raise HTTPException(401, "Incorrect password")
        csrf = secrets.token_urlsafe(24)
        response.set_cookie(
            "daydokuthon_session",
            signed_session(csrf),
            max_age=8 * 3600,
            httponly=True,
            secure=settings.secure_cookie,
            samesite="strict",
        )
        return {"csrf_token": csrf}

    @app.get("/api/admin/session")
    def get_session(credentials: Admin):
        return {"csrf_token": credentials["csrf"]}

    @app.post("/api/admin/logout")
    def logout(response: Response, credentials: Admin):
        response.delete_cookie(
            "daydokuthon_session", secure=settings.secure_cookie, httponly=True, samesite="strict"
        )
        return {"status": "logged_out"}

    def challenge_or_404(identity: str):
        row = store.challenge(identity)
        if not row:
            raise HTTPException(404, "Challenge not found")
        return row

    @app.get("/api/challenges")
    def challenges():
        return store.challenges()

    @app.get("/api/challenges/{identity}/download")
    def download_challenge(identity: str):
        return JSONResponse(
            as_challenge(challenge_or_404(identity)).to_dict(),
            headers={"Content-Disposition": 'attachment; filename="challenge.json"'},
        )

    @app.get("/api/challenges/{identity}/puzzle")
    def puzzle(identity: str):
        return puzzle_metadata(as_challenge(challenge_or_404(identity)))

    @app.post("/api/admin/challenges")
    def create_challenge(body: NewChallenge, credentials: Admin):
        if not body.title.strip():
            raise HTTPException(422, "Title cannot be blank")
        if body.opens_at and body.closes_at and body.opens_at >= body.closes_at:
            raise HTTPException(422, "Closing time must be after opening time")
        return store.create_challenge(
            {
                "title": body.title.strip(),
                "date": body.date,
                "puzzle_version": PUZZLE_VERSION,
                "opens_at": timestamp(body.opens_at) if body.opens_at else None,
                "closes_at": timestamp(body.closes_at) if body.closes_at else None,
                "created_at": timestamp(utc_now()),
            }
        )

    @app.post("/api/admin/challenges/{identity}/close")
    def close_challenge(identity: str, credentials: Admin):
        challenge_or_404(identity)
        store.close_challenge(identity)
        return {"status": "closed"}

    def receipt(row: dict):
        report = json.loads(row["report"])
        return {
            "id": row["id"],
            "challenge_id": row["challenge_id"],
            "roll_number": row["roll_number"],
            "received_at": row["received_at"],
            "eligible": bool(row["eligible"]),
            "eligibility_reason": row["eligibility_reason"],
            "passed": bool(row["eligible"]) and report["legal"] and report["solved"],
            "report": report,
        }

    @app.post("/api/challenges/{identity}/submissions", status_code=201)
    async def submit(identity: str, request: Request):
        challenge_or_404(identity)
        try:
            roll = unquote(request.headers.get("x-roll-number", ""), errors="strict").strip()
        except UnicodeError as error:
            raise HTTPException(422, "Invalid roll number encoding") from error
        if not roll or len(roll) > 64 or any(ord(c) < 32 or ord(c) == 127 for c in roll):
            raise HTTPException(
                422, "Roll number must be 1–64 characters without control characters"
            )
        raw = await bounded_body(request, settings.max_bytes)
        received = utc_now()
        row = challenge_or_404(identity)
        report = await run_in_threadpool(
            validate_trace,
            raw,
            as_challenge(row),
            max_bytes=settings.max_bytes,
            max_actions=settings.max_actions,
        )
        allowed, reason = eligibility(row, received)
        token = secrets.token_urlsafe(32)
        record = {
            "id": secrets.token_hex(16),
            "challenge_id": identity,
            "roll_number": roll,
            "received_at": timestamp(received),
            "raw": raw,
            "token_hash": hashlib.sha256(token.encode()).hexdigest(),
            "report": report.to_dict(),
            "eligible": allowed,
            "eligibility_reason": reason,
        }
        await run_in_threadpool(store.save_attempt, record)
        result = receipt({**record, "report": json.dumps(record["report"])})
        result["receipt_token"] = token
        return result

    def authorized_attempt(identity: str, request: Request):
        row = store.attempt(identity)
        token = request.headers.get("x-receipt-token", "")
        if not row or not (
            session(request)
            or hmac.compare_digest(hashlib.sha256(token.encode()).hexdigest(), row["token_hash"])
        ):
            raise HTTPException(404, "Receipt not found or access token invalid")
        return row

    @app.get("/api/submissions/{identity}")
    def get_receipt(identity: str, request: Request):
        return receipt(authorized_attempt(identity, request))

    @app.get("/api/submissions/{identity}/download")
    def get_raw(identity: str, request: Request):
        row = authorized_attempt(identity, request)
        return Response(
            row["raw"],
            media_type="application/octet-stream",
            headers={"Content-Disposition": f'attachment; filename="{identity}.json"'},
        )

    @app.get("/api/admin/attempts")
    def attempts(
        credentials: Admin, challenge_id: str | None = None, roll_number: str | None = None
    ):
        return [receipt(row) for row in store.attempts(challenge_id, roll_number)]

    @app.get("/api/admin/export")
    def export(credentials: Admin, challenge_id: str | None = None, roll_number: str | None = None):
        stream = io.StringIO()
        writer = csv.writer(stream)
        writer.writerow(
            [
                "id",
                "challenge_id",
                "roll_number",
                "received_at",
                "legal",
                "solved",
                "eligible",
                "passed",
                "eligibility_reason",
                "action_count",
            ]
        )
        for row in store.attempts(challenge_id, roll_number):
            entry = receipt(row)
            # Prevent spreadsheet formula interpretation of user-supplied roll numbers.
            roll = entry["roll_number"]
            if roll.startswith(("=", "+", "-", "@")):
                roll = "'" + roll
            writer.writerow(
                [
                    entry["id"],
                    entry["challenge_id"],
                    roll,
                    entry["received_at"],
                    entry["report"]["legal"],
                    entry["report"]["solved"],
                    entry["eligible"],
                    entry["passed"],
                    entry["eligibility_reason"],
                    entry["report"]["action_count"],
                ]
            )
        return Response(
            stream.getvalue(),
            media_type="text/csv",
            headers={"Content-Disposition": 'attachment; filename="attempts.csv"'},
        )

    _assets(app)
    return app


def create_replay_app(challenge: Challenge, raw: bytes) -> FastAPI:
    app = FastAPI(title="Daydokuthon local replay")
    _headers(app)
    if len(raw) > DEFAULT_MAX_BYTES:
        raise ValueError("Trace exceeds the local replay byte limit")
    report = validate_trace(raw, challenge)

    @app.get("/api/config")
    def config():
        return {
            "mode": "local",
            "challenge": challenge.to_dict(),
            "puzzle": puzzle_metadata(challenge),
            "report": report.to_dict(),
        }

    @app.get("/health")
    def health():
        return {"status": "ok"}

    _assets(app)
    return app
